css:
.p29-wrap { max-width: 56rem; margin-inline: auto; display: grid; gap: var(--s-4); }
.p29-top { display: grid; gap: var(--s-2); }
.p29-top:empty { display: none; }
.p29-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2); }
.p29-groups { display: grid; gap: var(--s-4); }
.p29-groups .group { gap: var(--s-2); }
.p29-list .rec__actions { flex-wrap: wrap; justify-content: flex-end; }
.p29-list .rec__actions .link-btn { margin-inline-start: var(--s-2); }
.p29-list .rec__title { display: inline-flex; align-items: center; min-height: var(--hit); }
.p29-ok { display: inline-grid; place-items: center; min-width: var(--hit); min-height: var(--hit); }
.p29-rtipw { grid-column: 1 / -1; }
.p29-rtip { display: flex; justify-content: flex-end; }
.p29-nolinks { padding: var(--s-1) 0; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p29-wrap.is-scrolled .p29-bar, .p29-wrap.is-scrolled .p29-above { display: none; } }
.p29-dis .link-btn[aria-disabled="true"] { color: var(--c-disabled-text); text-decoration: none; cursor: not-allowed; }
.p29-err { --frame-w: var(--w2); }
.p29-errbox { display: grid; gap: var(--s-3); justify-items: start; width: min(100%, 32rem); }
.p29-errbox .banner { width: 100%; }
.p29-center { min-height: calc(100cqh - 2 * var(--s-3)); display: grid; align-content: center; justify-items: center; gap: var(--s-3); text-align: center; padding: var(--s-5) var(--s-3); }
.p29-center p { max-width: var(--measure); }
.p29-load { justify-content: center; }
.p29-msg { color: var(--ink); max-width: var(--measure); }
.p29-nocards { display: grid; justify-items: start; gap: var(--s-3); padding: var(--s-4) 0; }
.p29-tiprow { display: flex; }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } .tabwrap > .tab { padding-inline: var(--s-1) 1.75rem; font-size: var(--fs-cap); } }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.dialog__head { align-items: center; }
.field__hint { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
